package com.coffeeshop.controller;import com.coffeeshop.dto.EmployeeCommands;import com.coffeeshop.model.EmployeeModels.*;import com.coffeeshop.security.ApplicationSession;import com.coffeeshop.service.EmployeeService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.GridPane;import java.time.LocalDate;import java.util.*;import java.util.concurrent.CompletableFuture;
public final class EmployeeManagementController{private static final List<String>STATES=List.of("ACTIVE","ON_LEAVE","TERMINATED");private final EmployeeService service;private final ApplicationSession session;@FXML private TextField searchField;@FXML private TableView<Employee>employeeTable;@FXML private TableColumn<Employee,String>numberColumn,nameColumn,titleColumn,statusColumn,userColumn,rolesColumn,activeColumn;@FXML private Label messageLabel;@FXML private Button editButton,accountButton,activeButton;public EmployeeManagementController(EmployeeService s,ApplicationSession a){service=Objects.requireNonNull(s);session=Objects.requireNonNull(a);}@FXML private void initialize(){numberColumn.setCellValueFactory(v->text(v.getValue().number()));nameColumn.setCellValueFactory(v->text(v.getValue().name()));titleColumn.setCellValueFactory(v->text(orDash(v.getValue().jobTitle())));statusColumn.setCellValueFactory(v->text(v.getValue().status().replace('_',' ')));userColumn.setCellValueFactory(v->text(orDash(v.getValue().username())));rolesColumn.setCellValueFactory(v->text(orDash(v.getValue().roles())));activeColumn.setCellValueFactory(v->text(v.getValue().active()?"Active":"Inactive"));searchField.textProperty().addListener((o,a,b)->refresh());employeeTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->selection(b));refresh();}@FXML private void refresh(){CompletableFuture.supplyAsync(()->service.employees(searchField.getText())).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load employees.");return;}employeeTable.getItems().setAll(v);messageLabel.setText(v.isEmpty()?"No employees match the search.":"");selection(employeeTable.getSelectionModel().getSelectedItem());}));}@FXML private void add(){employeeEditor(null).ifPresent(this::saveEmployee);}@FXML private void edit(){Employee e=selected();if(e!=null)employeeEditor(e).ifPresent(this::saveEmployee);}@FXML private void toggle(){Employee e=selected();if(e!=null)write(()->service.setActive(e,!e.active()),e.active()?"Employee deactivated.":"Employee activated.");}@FXML private void account(){Employee e=selected();if(e==null)return;List<Role>roles=service.roles();Dialog<EmployeeCommands.SaveUser>d=new Dialog<>();d.setTitle(e.userId()==null?"Create user account":"Edit user account");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,save);TextField username=new TextField(orEmpty(e.username()));PasswordField password=new PasswordField();password.setPromptText(e.userId()==null?"Minimum 12 characters":"Leave blank to keep current password");ListView<Role>roleList=new ListView<>();roleList.getItems().setAll(roles);roleList.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);if(e.roles()!=null)for(Role r:roles)if(Arrays.asList(e.roles().split(", ")).contains(r.code()))roleList.getSelectionModel().select(r);roleList.setPrefHeight(110);CheckBox mustChange=new CheckBox("Require password change"),active=new CheckBox("User active");mustChange.setSelected(true);active.setSelected(e.userId()==null||e.userActive());GridPane p=form();field(p,0,"Username",username);field(p,1,"Password",password);field(p,2,"Roles",roleList);p.add(mustChange,1,3);p.add(active,1,4);d.getDialogPane().setContent(p);d.setResultConverter(b->b==save?new EmployeeCommands.SaveUser(e.userId(),e.id(),username.getText(),password.getText().toCharArray(),mustChange.isSelected(),active.isSelected(),roleList.getSelectionModel().getSelectedItems().stream().map(Role::id).collect(java.util.stream.Collectors.toSet()),e.userVersion()):null);d.showAndWait().ifPresent(q->write(()->service.saveUser(q,session.currentUser().orElseThrow().userId()),"User account saved."));password.clear();}
 private Optional<EmployeeCommands.SaveEmployee>employeeEditor(Employee e){Dialog<EmployeeCommands.SaveEmployee>d=new Dialog<>();d.setTitle(e==null?"Add employee":"Edit employee");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,save);TextField number=f(e==null?null:e.number()),first=f(e==null?null:e.firstName()),last=f(e==null?null:e.lastName()),phone=f(e==null?null:e.phone()),email=f(e==null?null:e.email()),title=f(e==null?null:e.jobTitle());DatePicker hire=new DatePicker(e==null?LocalDate.now():e.hireDate()),termination=new DatePicker(e==null?null:e.terminationDate());ComboBox<String>status=new ComboBox<>();status.getItems().setAll(STATES);status.setValue(e==null?"ACTIVE":e.status());CheckBox active=new CheckBox("Active");active.setSelected(e==null||e.active());GridPane p=form();Control[]cs={number,first,last,phone,email,title,hire,termination,status};String[]ls={"Employee number","First name","Last name","Phone","Email","Job title","Hire date","Termination date","Status"};for(int i=0;i<ls.length;i++)field(p,i,ls[i],cs[i]);p.add(active,1,9);d.getDialogPane().setContent(p);d.getDialogPane().setPrefWidth(520);d.setResultConverter(b->b==save?new EmployeeCommands.SaveEmployee(e==null?null:e.id(),number.getText(),first.getText(),last.getText(),phone.getText(),email.getText(),title.getText(),hire.getValue(),termination.getValue(),status.getValue(),active.isSelected(),e==null?null:e.version()):null);return d.showAndWait();}private void saveEmployee(EmployeeCommands.SaveEmployee q){write(()->service.saveEmployee(q),"Employee saved.");}private void write(Runnable task,String ok){CompletableFuture.runAsync(task).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText(ok);}else messageLabel.setText(message(e));}));}private Employee selected(){return employeeTable.getSelectionModel().getSelectedItem();}private void selection(Employee e){editButton.setDisable(e==null);accountButton.setDisable(e==null);activeButton.setDisable(e==null);activeButton.setText(e==null||e.active()?"Deactivate":"Activate");}private static GridPane form(){GridPane p=new GridPane();p.setHgap(12);p.setVgap(8);return p;}private static void field(GridPane p,int row,String n,Control c){p.add(new Label(n),0,row);c.setMaxWidth(Double.MAX_VALUE);p.add(c,1,row);}private static TextField f(String s){return new TextField(orEmpty(s));}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String orEmpty(String s){return s==null?"":s;}private static String orDash(String s){return s==null||s.isBlank()?"-":s;}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to update employee data.";}}
